public void batchExport(BatchExportBo bo, OutputStream outputStream) {
    // LinkedHashSet：按首次出现顺序求并集，导出的列序每次一致
    Set<String> fields = new LinkedHashSet<>();
    Map<String, Map<String, String>> langData = new LinkedHashMap<>();
    for (String lang : bo.getLanguageCodes()) {
        List<ProductTranslate> list = productTranslateDao.findProductTranslateByLanguage(
                bo.getProductModel(), bo.getProductVersion(), lang);
        if (CollectionUtils.isEmpty(list)) {
            continue;                  // 该语言没数据就跳过，不报错也不留空列
        }
        Map<String, String> fieldToText = new LinkedHashMap<>();
        for (ProductTranslate t : list) {
            fieldToText.put(t.getField(), t.getText());
            fields.add(t.getField());
        }
        langData.put(lang, fieldToText);
    }
    List<List<String>> rows = buildRows(fields, langData, bo.getOnlyUntranslated());
    writeSingleSheet(outputStream, fields, rows);
}

private boolean isUntranslated(String field, String text, Map<String, String> zhMap) {
    if (StringUtils.isBlank(text)) {
        return true;
    }
    // 中文列取第一次见到的值作为基准，用于识别「照抄原文」
    String zh = zhMap.get(field);
    if (StringUtils.isNotBlank(zh) && StringUtils.equals(zh.trim(), text.trim())) {
        return true;
    }
    return false;
}
